function validate([word]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 1000) return 'word needs 1 to 1000 characters.';
  if (!/^[a-z0-9]+$/.test(word)) return 'word may contain only digits and lowercase letters.';
  return null;
}

