function numDifferentIntegers(word) {
  const seen = new Set();
  const n = word.length;
  let i = 0;

  while (i < n) {
    if (word[i] < '0' || word[i] > '9') {
      i++;
      continue;
    }
    while (i < n && word[i] === '0') {
      i++;
    }
    const start = i;
    while (i < n && word[i] >= '0' && word[i] <= '9') {
      i++;
    }
    seen.add(word.slice(start, i));
  }
  return seen.size;
}

