function generate(rand, size) {
  const length = size === 'large' ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 12);
  const letterRate = 0.15 + rand() * 0.5;
  const digits = rand() < 0.5 ? '0012' : '0123456789';
  let word = '';
  for (let i = 0; i < length; i++) {
    if (rand() < letterRate) word += 'abcxyz'[Math.floor(rand() * 6)];
    else word += digits[Math.floor(rand() * digits.length)];
  }
  return [word];
}
